-- Final Journey One workbook section from six-week Curriculum Master v2.0.
-- Security-definer workbook access determines per-enrollment scheduled visibility.
update public.aca_phase_two_workbook_definitions
set content=jsonb_set(content,'{pages}',coalesce(content->'pages','[]'::jsonb)||'{"number":6,"lesson_id":"1.6","kicker":"JOURNEY ONE / LESSON 1.6","title":"Stress Test the Professional Operating Model","blocks":[{"type":"heading","text":"Finish Journey One with a working professional model"},{"type":"text","text":"This workbook section is a permanent study and revision resource. Your Professional AI Operating Model governs how you work, not a software architecture or permission to deploy. Bring forward your Project Record from Lessons 1.1–1.5: purpose, affected person, observed need, AI support role, useful measure, decisions, review criteria and feasible FOCUS charter."},{"type":"note","title":"Your six-part Professional AI Operating Model","text":"1. Purpose and outcome. 2. AI support roles or no AI. 3. Human responsibilities and final decision ownership. 4. Review process and current approved evidence. 5. Responsible privacy, authority and consequence boundaries. 6. Growth and future correction commitments.","theme":"gold"},{"type":"field","id":"p2-j1-6-purpose","label":"Purpose: Who is served, what task matters, and what result is useful?","hint":"","lines":5},{"type":"field","id":"p2-j1-6-role","label":"AI support: What narrow tasks may AI do, and when should it NOT be used?","hint":"","lines":5},{"type":"field","id":"p2-j1-6-human","label":"Human responsibility: Who supplies evidence, reviews results, approves consequential action and resolves exceptions?","hint":"","lines":5},{"type":"field","id":"p2-j1-6-review","label":"Review process: Which current approved source is checked, by whom, and what causes withholding?","hint":"","lines":5},{"type":"field","id":"p2-j1-6-boundaries","label":"Responsible boundaries: What sensitive records, external commitments or missing permissions trigger a pause?","hint":"","lines":5},{"type":"field","id":"p2-j1-6-growth","label":"Growth: What professional capability will you strengthen, and what new evidence would cause you to revise the model?","hint":"","lines":5},{"type":"heading","text":"Adjust review depth to the consequence"},{"type":"text","text":"Verify accuracy, usefulness, suitability for people affected, sensitive information and whether you can explain the result. Routine fictional practice may use a light check. An outward customer message requires current approved policies and a named reviewer. Binding decisions or private data require verified permission and appropriate human authority."},{"type":"note","title":"Fictional outdated-policy example","text":"An AI drafts a courteous customer message using a previous policy version. The weak rule, ''Check the answer,'' lacks a source, reviewer and hold instruction. A stronger rule says: use the latest approved policy; the named reviewer verifies; if the source is missing or conflicting, do not send and escalate to the policy owner.","theme":"gold"},{"type":"heading","text":"Run three stress-test scenarios"},{"type":"field","id":"p2-j1-6-routine","label":"Scenario 1 — Routine task: describe safe fictional input, AI role or no AI, reviewer, needed check and proceed/pause decision.","hint":"Choose a reversible, low-consequence case.","lines":5},{"type":"field","id":"p2-j1-6-inaccurate","label":"Scenario 2 — Inaccurate AI output: identify unsupported wording or outdated policy, approved source, human reviewer and correction/hold response.","hint":"Do not let polished text substitute for verification.","lines":5},{"type":"field","id":"p2-j1-6-high","label":"Scenario 3 — Higher consequence: privacy or authority problem, affected person, limits, escalation owner and required approval.","hint":"Use only fictional examples. Never paste real confidential records.","lines":5},{"type":"heading","text":"Challenge your model in your own AI tool"},{"type":"text","text":"Copy the approved challenge request into ChatGPT or another AI assistant on your own phone, tablet or computer. Insert only fictional or authorized sanitized project details. Review every suggestion against actual responsibilities and known sources. This practice cannot approve deployment or grant a credential."},{"type":"note","title":"Copyable approved AI request","text":"Challenge this operating model with a routine case, an inaccurate response and a high-consequence request. Identify weaknesses and missing human owners. Suggest corrections for my review. Model: [sanitized draft].","theme":"gold"},{"type":"field","id":"p2-j1-6-original","label":"Original rule or operating model section that your stress test examined.","hint":"","lines":5},{"type":"field","id":"p2-j1-6-revised","label":"Revised or evidence-justified rule. Name the approved source, reviewing owner and explicit action under uncertainty.","hint":"","lines":5},{"type":"field","id":"p2-j1-6-change","label":"Explain what changed and why, or why the existing rule was justified by evidence.","hint":"","lines":5},{"type":"heading","text":"Defend one proceed and one pause"},{"type":"field","id":"p2-j1-6-proceed","label":"PROCEED: Which task can continue? State permitted information, scope, human review and why consequences are acceptable.","hint":"","lines":5},{"type":"field","id":"p2-j1-6-pause","label":"PAUSE: Which task must stop? State source/permission gap, consequence, accountable owner and evidence required before resuming.","hint":"","lines":5},{"type":"heading","text":"Confirm the capstone and Journey One handoff"},{"type":"field","id":"p2-j1-6-charter","label":"Copy or revise the feasible FOCUS charter: Function, Owner, Customer, Use Case, Scope. Name one realistic first test.","hint":"Do not replace the earlier Project Record; this is a review copy.","lines":5},{"type":"field","id":"p2-j1-6-project","label":"Confirm the project''s current direction and one outstanding permission, risk or dependency.","hint":"","lines":5},{"type":"field","id":"p2-j1-6-reflection","label":"Explain how your revised operating rule improves real accountability rather than just generating more text.","hint":"","lines":5},{"type":"note","title":"Journey One completed — keep the evidence","text":"Save your original/revised model, three scenario results, proceed/pause decisions and confirmed charter into the same continuing Project Record. Download or print this released workbook to review independently. The tested model accompanies your project into Journey Two: Build AI into Business Workflows. Next journey material stays unavailable until scheduled release.","theme":"gold"}]}'::jsonb,true),version=version+1,updated_at=now()
where journey_number=1 and not exists(select 1 from jsonb_array_elements(content->'pages') p where p->>'lesson_id'='1.6');
